import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours annuel complémentaire de 5e : 18 unités, six par trimestre.
class CinquiemeCompletionScreen extends StatelessWidget {
  const CinquiemeCompletionScreen({super.key});
  static const _units = <_Unit>[
    _Unit('T1 • Français','Le récit, les temps et les fonctions','Un récit organise des événements dans un ordre compréhensible. Le narrateur peut parler à la première personne (je/nous) ou à la troisième personne (il/elle/ils). Je distingue l’auteur, le narrateur et les personnages. Le passé simple présente souvent les actions successives de premier plan ; l’imparfait installe le décor, décrit ou exprime une habitude. Le sujet commande l’accord du verbe. Pour analyser un récit, je repère le cadre, les personnages, le déclencheur, les péripéties et la situation finale.','La pluie tombait (description) quand le voyageur entra (action).','Dans cette phrase, quel temps exprime l’action principale : « Il marchait quand il aperçut la maison » ?',['Imparfait','Passé simple','Futur'],1,'Aperçut est au passé simple et marque l’action soudaine.'),
    _Unit('T1 • Mathématiques','Nombres relatifs et opérations','Un nombre relatif est positif, négatif ou nul. Sur une droite graduée, les nombres augmentent vers la droite ; deux nombres opposés ont la même distance à zéro et des signes contraires. Pour additionner deux nombres de même signe, on additionne leurs distances à zéro et on garde le signe. Pour des signes contraires, on soustrait les distances et on garde le signe du nombre ayant la plus grande valeur absolue. Pour multiplier ou diviser, deux signes identiques donnent un résultat positif et deux signes différents un résultat négatif. Je vérifie avec une estimation.','−7 + 3 = −4 ; (−2) × 5 = −10.','Calcule −8 + 13.',['−21','5','−5'],1,'Les signes sont différents : 13 − 8 = 5, avec le signe du nombre de plus grande valeur absolue.'),
    _Unit('T1 • Anglais','Daily routines and present simple','Le present simple exprime les habitudes, les routines et les vérités générales. À la troisième personne du singulier, on ajoute généralement -s ou -es ; les verbes terminés par consonne + y changent souvent y en -ies. Les questions utilisent do ou does, puis le sujet et la base verbale. La négation utilise do not ou does not. Après does/doesn’t, le verbe ne prend pas -s. Je sais parler de mes horaires, de mes loisirs et de mes responsabilités quotidiennes.','She studies every evening. Does he play football?','Choose the correct sentence.',['He go to school.','He goes to school.','He going to school.'],1,'Avec he, le verbe prend généralement -s : goes.'),
    _Unit('T1 • SVT','Nutrition des plantes et organisation des êtres vivants','Les végétaux chlorophylliens fabriquent leur matière organique à partir d’eau, de sels minéraux et de dioxyde de carbone grâce à l’énergie lumineuse : c’est la photosynthèse. Les racines absorbent l’eau et les sels minéraux ; la tige soutient la plante et transporte la sève ; les feuilles captent la lumière et réalisent l’essentiel de la photosynthèse. Une plante a aussi besoin d’un milieu adapté. Je compare les organes et leurs fonctions à partir d’observations.','Les racines absorbent l’eau et les sels minéraux du sol.','Quel organe absorbe principalement l’eau du sol ?',['La fleur','La racine','Le fruit'],1,'Les racines prélèvent l’eau et les sels minéraux.'),
    _Unit('T1 • Physique-Chimie','Masse, volume et états de la matière','La matière existe principalement sous les états solide, liquide et gazeux. Un solide conserve généralement sa forme propre ; un liquide prend la forme du récipient et possède un volume propre ; un gaz occupe tout l’espace disponible. La masse se mesure avec une balance, le volume avec une éprouvette graduée. Lors d’un changement d’état, la nature chimique du corps reste la même. Je distingue fusion, solidification, vaporisation et liquéfaction et note les unités correctement.','Un glaçon qui fond devient de l’eau liquide : c’est la fusion.','Quelle unité convient pour mesurer le volume d’un liquide ?',['Le litre','Le kilogramme','Le degré Celsius'],0,'Le litre et le millilitre sont des unités de volume.'),
    _Unit('T1 • Histoire-Géographie-EMC','Repères historiques et géographiques du Togo','Une carte permet de localiser des lieux grâce à son titre, sa légende, son échelle et son orientation. Le Togo se situe en Afrique de l’Ouest, entre notamment le Ghana et le Bénin, et possède une façade sur le golfe de Guinée. Je sais utiliser les points cardinaux et lire une légende. Une frise classe les événements du plus ancien au plus récent ; je vérifie les dates et l’intervalle représenté. Je distingue source, date et nature d’un document historique.','Sur une carte, la flèche du nord aide à orienter les directions.','Quel océan borde le sud du Togo ?',['Océan Indien','Océan Atlantique','Océan Pacifique'],1,'Le littoral togolais donne sur le golfe de Guinée, dans l’Atlantique.'),
    _Unit('T2 • Français','Accords, propositions et discours rapporté','Dans le groupe nominal, déterminant, nom et adjectif s’accordent en genre et en nombre. Je distingue les classes grammaticales des fonctions : sujet, complément d’objet direct ou indirect, complément circonstanciel. Une proposition contient un verbe conjugué. Le discours direct rapporte les paroles avec guillemets et ponctuation ; le discours indirect les intègre au récit et peut modifier les pronoms, les temps et les repères. Je justifie chaque identification en posant une question adaptée.','Les jeunes filles attentives écoutent. « Il vient », dit-elle : elle dit qu’il vient.','Quelle phrase est correctement accordée ?',['Ces élèves sérieux travaillent.','Ces élèves sérieuse travaille.','Cet élèves sérieux travaille.'],0,'Élèves est masculin pluriel : ces et sérieux s’accordent au pluriel.'),
    _Unit('T2 • Mathématiques','Fractions, calcul littéral et proportionnalité','Pour additionner ou soustraire des fractions, je les réduis au même dénominateur puis j’effectue l’opération sur les numérateurs. Pour multiplier deux fractions, je multiplie les numérateurs entre eux et les dénominateurs entre eux, puis je simplifie. Une expression littérale contient des lettres qui représentent des nombres ; je remplace chaque lettre par sa valeur en respectant les priorités. Deux grandeurs sont proportionnelles si le quotient correspondant reste constant. Je vérifie un tableau par le coefficient de proportionnalité.','1/3 + 1/6 = 2/6 + 1/6 = 1/2 ; si y = 3x, alors x = 4 donne y = 12.','Calcule 2/5 + 1/5.',['3/5','2/10','3/10'],0,'Les dénominateurs sont identiques : on additionne les numérateurs.'),
    _Unit('T2 • Anglais','Past simple and describing past events','Le past simple décrit une action terminée dans le passé. Les verbes réguliers prennent souvent -ed, avec quelques règles d’orthographe ; les verbes irréguliers ont une forme particulière à mémoriser. Les questions et négations utilisent did, suivi de la base verbale. Je repère les marqueurs temporels last…, yesterday et ago. Je raconte un événement passé en ordonnant les actions et en ajoutant des détails sur le lieu et les personnes.','We visited Kpalimé last year. Did you see the waterfall?','Choose the past form of « go ».',['goed','went','goes'],1,'Go est irrégulier : son prétérit est went.'),
    _Unit('T2 • SVT','Respiration et échanges gazeux','La respiration permet aux organismes de réaliser des échanges gazeux avec leur milieu. Chez l’être humain, l’air circule par les voies respiratoires jusqu’aux poumons ; au niveau des alvéoles, le dioxygène passe dans le sang et le dioxyde de carbone est rejeté. Le sang transporte le dioxygène vers les organes. L’activité physique augmente les besoins en dioxygène. Je relie respiration, circulation et hygiène de vie, sans confondre respiration et mouvements respiratoires.','L’activité physique augmente les besoins des muscles en dioxygène.','Quel gaz passe des alvéoles pulmonaires vers le sang ?',['Dioxygène','Azote uniquement','Vapeur d’eau uniquement'],0,'Le dioxygène diffuse des alvéoles vers les capillaires sanguins.'),
    _Unit('T2 • Physique-Chimie','Mélanges, solutions et séparation','Un mélange homogène présente un aspect uniforme ; un mélange hétérogène laisse distinguer plusieurs constituants. Une solution est un mélange homogène obtenu lorsqu’un soluté se dissout dans un solvant. La décantation sépare des constituants de densités différentes, la filtration retient un solide insoluble et l’évaporation peut récupérer un solide dissous. Je choisis la technique en fonction du mélange et j’explique ce que devient chaque constituant.','Le sable dans l’eau forme un mélange hétérogène que l’on peut filtrer.','Quelle technique retient le sable et laisse passer l’eau ?',['Filtration','Fusion','Aimantation dans tous les cas'],0,'Le filtre retient les particules solides insolubles.'),
    _Unit('T2 • Histoire-Géographie-EMC','Population, activités et organisation du territoire','La population se répartit inégalement selon les ressources, les emplois, les transports, le relief et les services. L’agriculture, l’artisanat, le commerce et l’industrie participent à l’économie et créent des échanges entre les territoires. Je lis un tableau ou un graphique simple pour comparer des données. Le citoyen respecte les biens publics, les droits d’autrui et participe à la vie collective. Je distingue besoin, ressource, production et consommation.','Un marché relie producteurs, commerçants et consommateurs.','Quel indicateur correspond au nombre d’habitants d’un territoire ?',['La population','La température','La superficie seule'],0,'La population désigne l’ensemble des habitants d’un territoire.'),
    _Unit('T3 • Français','Argumentation, poésie et rédaction','Un texte argumentatif défend une thèse à l’aide d’arguments expliqués et d’exemples précis. Les connecteurs organisent le raisonnement : d’abord, ensuite, en effet, cependant, donc. Je distingue opinion et fait vérifiable. Un poème peut jouer sur les images, les comparaisons, les métaphores, les sonorités et le rythme. Pour rédiger, je construis une introduction, des paragraphes organisés et une conclusion, puis je relis la cohérence et la langue.','Thèse : protéger les arbres ; argument : ils limitent l’érosion ; exemple : les haies retiennent le sol.','Quel connecteur introduit une opposition ?',['Donc','Cependant','Ainsi'],1,'Cependant annonce une opposition ou une nuance.'),
    _Unit('T3 • Mathématiques','Triangles, angles, périmètres et aires','La somme des angles d’un triangle vaut 180°. Je classe les triangles selon leurs côtés et leurs angles, puis j’utilise règle, compas et rapporteur pour construire ou mesurer. Le périmètre est la longueur du contour. L’aire mesure la surface : pour un triangle, A = base × hauteur ÷ 2 ; pour un rectangle, A = longueur × largeur. Les unités d’aire sont au carré. Je trace la hauteur perpendiculaire à la base avant le calcul.','Triangle de base 8 cm et hauteur 5 cm : A = 8 × 5 ÷ 2 = 20 cm².','Un triangle a deux angles de 50° et 60°. Le troisième vaut…',['70°','90°','110°'],0,'180° − 50° − 60° = 70°.'),
    _Unit('T3 • Anglais','Future forms and giving advice','Will sert notamment à exprimer une décision spontanée ou une prévision. Be going to exprime souvent un projet ou une intention déjà envisagée. Should permet de donner un conseil ; must exprime une obligation forte et mustn’t une interdiction. Je construis des phrases affirmatives, négatives et interrogatives et je distingue les auxiliaires. Je peux proposer des conseils pour la santé, les études et la protection de l’environnement.','You should revise. We are going to visit Lomé tomorrow.','Which sentence gives advice?',['You should drink water.','I drank water yesterday.','Water is cold.'],0,'Should sert à conseiller : tu devrais boire de l’eau.'),
    _Unit('T3 • SVT','Reproduction, santé et protection de l’environnement','La reproduction assure la continuité des espèces. La puberté correspond à des transformations physiques, physiologiques et émotionnelles variables selon les individus ; chacun doit être respecté. L’hygiène, la prévention et l’accès à une information fiable contribuent à la santé. La biodiversité dépend de la diversité des espèces et de la protection des habitats. Je sais citer des menaces (pollution, destruction des milieux, surexploitation) et des actions de préservation.','Protéger une mare et éviter d’y jeter des déchets préserve les organismes qui y vivent.','Quel comportement protège la biodiversité ?',['Détruire les habitats','Polluer les cours d’eau','Préserver les habitats naturels'],2,'La conservation des habitats protège les espèces et les équilibres écologiques.'),
    _Unit('T3 • Physique-Chimie','Électricité, circuits et sécurité','Un circuit électrique simple comporte un générateur, des conducteurs et un récepteur. Le courant circule lorsque le circuit est fermé et que les connexions sont correctes. Un interrupteur ouvre ou ferme le circuit. Je représente un montage par un schéma avec des symboles conventionnels et distingue montage en série et dérivation à un niveau introductif. Je n’utilise que du matériel scolaire basse tension ; je ne manipule jamais une prise, un fil dénudé ou un appareil endommagé.','Une pile reliée correctement à une lampe par des fils forme un circuit fermé.','Dans quel cas la lampe peut-elle s’allumer ?',['Circuit ouvert','Circuit fermé avec générateur','Fils non reliés'],1,'Le circuit doit être fermé et comporter un générateur fonctionnel.'),
    _Unit('T3 • Histoire-Géographie-EMC','Développement durable et préparation au cycle suivant','Le développement durable cherche à concilier protection de l’environnement, progrès social et activités économiques, en préservant les ressources pour l’avenir. Les risques naturels et les actions humaines doivent être étudiés à partir d’observations, de cartes et de documents fiables. Je propose des actions concrètes : économiser l’eau et l’énergie, réduire les déchets, planter et protéger les sols. Pour préparer la classe suivante, je révise les méthodes de lecture, de calcul, d’argumentation et de rédaction.','Économiser l’eau, planter des arbres et réduire les déchets sont des gestes responsables.','Quel principe correspond au développement durable ?',['Utiliser les ressources sans limite','Répondre aux besoins actuels sans compromettre l’avenir','Supprimer toute activité humaine'],1,'Le développement durable protège les possibilités des générations futures.'),
  ];

  static int get unitCount => _units.length;
  static int get lessonCount => _units.length;
  static List<Exercise> assessmentExercisesForTerm(int term, {String? subjectName}) {
    final prefix = 'T$term •';
    final result = <Exercise>[];
    for (var i = 0; i < _units.length; i++) {
      final unit = _units[i];
      if (!unit.title.startsWith(prefix)) continue;
      if (subjectName != null && !_matches(unit.title, subjectName)) continue;
      result.add(Exercise(id: 'five_t${term}_u${i}', lessonId: 'five_t${term}_u${i}', question: unit.question, options: unit.options, correctIndex: unit.answer, explanation: unit.explanation));
    }
    return result;
  }
  static bool _matches(String title, String subject) {
    final t = title.toLowerCase(), s = subject.toLowerCase();
    if (s.contains('français') || s.contains('francais')) return t.contains('français');
    if (s.contains('math')) return t.contains('mathématiques');
    if (s.contains('anglais') || s.contains('english')) return t.contains('anglais');
    if (s.contains('svt') || s.contains('science')) return t.contains('svt');
    if (s.contains('physique') || s.contains('chimie') || s.contains('technologie')) return t.contains('physique-chimie');
    if (s.contains('histoire') || s.contains('géographie') || s.contains('education') || s.contains('éducation') || s.contains('emc')) return t.contains('histoire-géographie-emc');
    return false;
  }
  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Complément 5ème • Année complète')),
    body: ListView(padding: const EdgeInsets.all(16), children: [
      Card(child: Padding(padding: const EdgeInsets.all(16), child: Text('${unitCount} unités • ${lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds puis consulte la correction.', style: const TextStyle(fontWeight: FontWeight.w600)))),
      for (final unit in _units) _UnitTile(unit: unit),
    ]),
  );
}
class _Unit {
  final String title, objective, content, example, question;
  final List<String> options;
  final int answer;
  final String explanation;
  const _Unit(this.title, this.objective, this.content, this.example, this.question, this.options, this.answer, this.explanation);
}
class _UnitTile extends StatefulWidget {
  final _Unit unit;
  const _UnitTile({required this.unit});
  @override State<_UnitTile> createState() => _UnitTileState();
}
class _UnitTileState extends State<_UnitTile> {
  int? choice;
  bool checked = false;
  @override Widget build(BuildContext context) {
    final unit = widget.unit;
    return Card(margin: const EdgeInsets.only(bottom: 10), child: ExpansionTile(
      title: Text(unit.title, style: const TextStyle(fontWeight: FontWeight.bold)),
      subtitle: Text(unit.objective),
      children: [Padding(padding: const EdgeInsets.fromLTRB(16, 0, 16, 16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(unit.content), const SizedBox(height: 8),
        Text('Exemple : ${unit.example}', style: const TextStyle(fontStyle: FontStyle.italic)),
        const SizedBox(height: 12), Text(unit.question, style: const TextStyle(fontWeight: FontWeight.bold)),
        for (var i = 0; i < unit.options.length; i++) RadioListTile<int>(dense: true, contentPadding: EdgeInsets.zero, value: i, groupValue: choice, title: Text(unit.options[i]), onChanged: checked ? null : (value) => setState(() => choice = value)),
        FilledButton.tonal(onPressed: choice == null ? null : () => setState(() => checked = true), child: const Text('Vérifier ma réponse')),
        if (checked) Text('${choice == unit.answer ? 'Bonne réponse ! ' : 'À revoir. Bonne réponse : ${unit.options[unit.answer]}. '}${unit.explanation}', style: TextStyle(fontWeight: FontWeight.w600, color: choice == unit.answer ? Colors.green.shade800 : Theme.of(context).colorScheme.error)),
        if (checked) TextButton(onPressed: () => setState(() { choice = null; checked = false; }), child: const Text('Recommencer')),
      ]))],
    ));
  }
}
